// Compute derived values and publish them for the readouts to display.
// Re-run this cell after moving the Temperature / Radius sliders to refresh
// the computed readouts (JS cells run once; readouts don't recompute on their
// own — that's what the HTML bridge's nb.onChange is for, shown in band 8.2).
const c = nb.get('temp_c');
const r = nb.get('radius');

const f = c * 9 / 5 + 32;
const area = Math.PI * r * r;

nb.set('temp_f', f);
nb.set('area', area);

console.log(c, '°C =', f.toFixed(1), '°F');
console.log('radius', r, 'px → area', area.toFixed(2), 'px²');
return 'published temp_f + area — see the two computed readouts update ↑';

// Live values — note every one is a raw number; the °C / °F / px suffixes you
// see in the controls are formatting, not part of the stored value.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  temp_c: val('temp_c'),
  ratio:  val('ratio'),   // step 0.01, shown to 2 dp — but stored full-precision
  radius: val('radius'),
  temp_f: val('temp_f'),  // written by the JS cell above
  area:   val('area'),
};
